<?php
if($page==='admin-bookings'){
  require_admin();$q=trim((string)($_GET['q']??''));if($q!==''){$s=$pdo->prepare("SELECT b.*,u.name user_name,u.email,l.name location_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN locations l ON l.id=b.location_id WHERE b.code LIKE ? OR u.email LIKE ? OR u.name LIKE ? ORDER BY b.created_at DESC LIMIT 200");$like='%'.$q.'%';$s->execute([$like,$like,$like]);}else{$s=$pdo->query('SELECT b.*,u.name user_name,u.email,l.name location_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN locations l ON l.id=b.location_id ORDER BY b.created_at DESC LIMIT 200');}$list=$s->fetchAll();layout_start('Manage bookings',true);?>
  <section class="container section"><div class="section-head"><div><span class="eyebrow">Reservations</span><h1>Bookings</h1></div><form class="search-inline"><input type="hidden" name="page" value="admin-bookings"><input name="q" value="<?=e($q)?>" placeholder="Code, customer or email"><button class="btn btn-small">Search</button></form></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Customer</th><th>Location</th><th>Schedule</th><th>Total</th><th>Update</th></tr></thead><tbody><?php if(!$list):?><tr><td colspan="6">No bookings found.</td></tr><?php else:foreach($list as $b):?><tr><td><strong><?=e($b['code'])?></strong><br><small><?=date('M j, Y',strtotime($b['created_at']))?></small></td><td><?=e($b['user_name'])?><br><small><?=e($b['email'])?></small></td><td><?=e($b['location_name'])?></td><td><?=date('M j g:i A',strtotime($b['dropoff_at']))?><br><small>to <?=date('M j g:i A',strtotime($b['pickup_at']))?></small></td><td><?=e(money((float)$b['total_amount']))?><br><small><?=$b['bags']?> bags</small></td><td><form method="post" class="status-form"><?=csrf_field()?><input type="hidden" name="action" value="admin-booking-status"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><select name="status"><?php foreach(['confirmed','checked_in','completed','cancelled'] as $v):?><option value="<?=$v?>" <?=$b['status']===$v?'selected':''?>><?=str_replace('_',' ',$v)?></option><?php endforeach;?></select><select name="payment_status"><?php foreach(['unpaid','paid','refunded'] as $v):?><option value="<?=$v?>" <?=$b['payment_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn btn-small" type="submit">Save</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></section>
  <?php layout_end();exit;
}
